select '123789789012345' as codigo into #produtos

select *
  from #produtos

delete #produtos

drop table #produtos


select *
  from #produtos

select *
  from #produtos
 where codigo not in(select ProdutoCodigo from Produto with (nolock))

select *
  from Produto with (nolock)
 where ProdutoCodigo not in(select codigo from #produtos with (nolock))


select *
  from Categoria with (nolock)

select *
  from CategoriaSubcategoria with (nolock)
 where SubcategoriaIdPai=195

begin tran
update CategoriaSubcategoria
   set SubcategoriaNome='MARCADORES PERMANENTES'
 where SubcategoriaIdPai=195
       and SubcategoriaIdRef=379
commit tran

select *
  from Produto with (nolock)

create table prodescrweb (
   sku varchar(15)
   ,name varchar(600)
   ,description varchar(4000)
   ,short_description varchar(4000)
   ,aux char(1)
)

drop table prodescrweb

delete prodescrweb

select sku, name, description, short_description, ''
  --into prodescrweb
  from openrowset('Microsoft.ACE.OLEDB.12.0', 'Excel 12.0;Database=C:\integros\temp\produtos-web-tanby.xlsx', 'select * from [Planilha2$]')

select *
  from prodescrweb with (nolock)
 where sku='6533284'

select *
  into prodescrweb2
  from openrowset('Microsoft.ACE.OLEDB.12.0', 'Excel 12.0;Database=C:\integros\temp\produtos-web-tanby.xlsx', 'select sku, short_description from [Planilha2$]')

select *
  from prodescrweb2 with (nolock)
 where sku='6533284'

update prodescrweb
   set description=''
 where description is null

update prodescrweb
   set short_description=''
 where short_description is null

select *
  from Produto with (nolock)
       inner join prodescrweb with (nolock)
	   on prodescrweb.sku=Produto.ProdutoCodigo collate database_default

begin tran
update Produto
   set ProdutoDescricao=description
       ,ProdutoDescricaoResumida=short_description
  from Produto with (nolock)
       inner join prodescrweb with (nolock)
	   on prodescrweb.sku=Produto.ProdutoCodigo collate database_default
commit tran

